from decimal import Decimal; import pytest; from src.audit.money import MONEY_QUANTUM, to_money; pytestmark = pytest.mark.no_db
def test_money_quantum_is_two_decimal_places(): assert MONEY_QUANTUM == Decimal('0.01'); assert to_money(Decimal('10')) == Decimal('10.00'); assert to_money(Decimal('3.14159')) == Decimal('3.14'); assert to_money(Decimal('0.1')) == Decimal('0.10'); assert to_money(Decimal('-0.125')) == Decimal('-0.12'); assert to_money(Decimal('-0.145')) == Decimal('-0.14'); assert to_money(Decimal('99.99')) == Decimal('99.99'); assert to_money(Decimal('-42.00')) == Decimal('-42.00')
@pytest.mark.parametrize('value,expected', [('0.125', '0.12'), ('0.135', '0.14'), ('0.145', '0.14'), ('0.155', '0.16'), ('2.005', '2.00')])
def test_to_money_uses_banker_rounding_half_to_even(value, expected): assert to_money(Decimal(value)) == Decimal(expected)
